// Кейс: .qa/tests/navigation/NAV-005.md (шаги 1–4) · план: .qa/e2e-app/specs/app.md (1.12)
// Ссылки на странице /about тест не нажимает; браузер закрывается только его кнопкой закрытия.
import { by, assert } from '../../lib/appium.mjs';
import { onHome, openTab, checkAboutPage, closeInAppBrowser } from '../../lib/banci.mjs';

export const name = '«חשבון» → «איך Banci עובדת» (между «התרעות וצפצוף» и «תנאי שימוש ודיסקליימר») → /about во встроенном браузере → закрыть #94e4f3 @iphone @app @prod-safe';

const ROW = 'איך Banci עובדת';
const ABOVE = 'התרעות וצפצוף';
const BELOW = 'תנאי שימוש ודיסקליימר';

export default async function (app) {
  // 1. «חשבון» → строка «איך Banci עובדת» между «התרעות וצפצוף» и «תנאי שימוש ודיסקליימר».
  await onHome(app);
  await openTab(app, 'חשבון');
  await app.scrollTo(by.begins(ROW), { what: `строка «${ROW}» в «חשבון»` });
  const below = await app.scrollTo(by.begins(BELOW), { max: 3, what: `строка «${BELOW}»` });
  const rowY = (await (await app.waitFor(by.begins(ROW), { what: `строка «${ROW}»` })).rect()).y;
  assert(rowY < (await below.rect()).y, `«${ROW}» выше «${BELOW}»`);
  const above = await app.scrollTo(by.begins(ABOVE), { max: 3, direction: 'up', what: `строка «${ABOVE}»` });
  const row2 = await app.waitFor(by.begins(ROW), { what: `строка «${ROW}»` });
  assert((await above.rect()).y < (await row2.rect()).y, `«${ABOVE}» выше «${ROW}»`);

  // 2–3. Тап → https://banci.expo.app/about во встроенном браузере: заголовок, разделы, «לא תחליף להשגחה», ссылка на условия.
  await row2.click();
  await checkAboutPage(app);

  // 4. Закрыть → снова «חשבון» со строкой «איך Banci עובדת».
  await closeInAppBrowser(app);
  await app.scrollTo(by.begins(ROW), { what: `после закрытия — «חשבון» со строкой «${ROW}»` });
}
